public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123  ".getBytes();
        // offset 0, length 8. Result should be 83 (123 octal)
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 8));
    }

    @Test
    public void testParseOctal_LeadingSpaces() {
        byte[] buffer = "   755".getBytes();
        // 755 octal = 7*64 + 5*8 + 5 = 448 + 40 + 5 = 493
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, 6));
    }

    @Test
    public void testParseOctal_LeadingZeros() {
        byte[] buffer = "0000007".getBytes();
        assertEquals(7L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_BufferStartZero() {
        byte[] buffer = new byte[]{0, 0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Test long capacity
        byte[] buffer = "777777777777".getBytes();
        long expected = Long.parseLong("777777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, 12));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = "1".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "0008".getBytes(); // 8 is not octal
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
